<script setup>
import { ref, shallowRef, watch } from 'vue';
import ToolIntro from '../../components/ToolIntro.vue';
import { compareText } from '../../utils/developerTools.js';
const left = ref('Hello Workbench\n版本：1.0\n准备开始'), right = ref('Hello Workbench\n版本：2.0\n准备开始\n新增工具');
const ignoreWhitespace = ref(false), ignoreCase = ref(false), onlyChanges = ref(false), error = ref(''), result = shallowRef(null);
watch([left, right, ignoreWhitespace, ignoreCase], () => { result.value = null; error.value = ''; });
function compare() { error.value = ''; try { result.value = compareText(left.value, right.value, { ignoreWhitespace: ignoreWhitespace.value, ignoreCase: ignoreCase.value }); } catch (e) { error.value = e.message; } }
compare();
</script>
<template><section><ToolIntro title="文本差异对比" eyebrow="DEVELOPER / DIFF" description="并排查看两份文本，快速找到每一处增加与删除。" /><div class="utility-grid"><section class="panel utility-panel"><label class="utility-field">原始文本<a-textarea v-model:value="left" aria-label="原始文本" :rows="10" class="utility-code" spellcheck="false" /></label></section><section class="panel utility-panel"><label class="utility-field">修改后文本<a-textarea v-model:value="right" aria-label="修改后文本" :rows="10" class="utility-code" spellcheck="false" /></label></section></div><div class="utility-toolbar utility-gap"><a-button type="primary" @click="compare">开始对比</a-button><a-button @click="[left, right] = [right, left]">交换两侧</a-button><a-checkbox v-model:checked="ignoreWhitespace">忽略空白字符</a-checkbox><a-checkbox v-model:checked="ignoreCase">忽略大小写</a-checkbox><a-checkbox v-model:checked="onlyChanges">仅看差异</a-checkbox></div><a-alert v-if="error" class="utility-error" :message="error" type="error" role="alert" /><section v-if="result" class="panel utility-panel utility-gap"><div class="panel-heading"><h2>对比结果</h2><span class="utility-status">+{{ result.added }} 行 / −{{ result.removed }} 行</span></div><p v-if="!result.added && !result.removed" class="utility-note">按当前规则，两份文本相同。</p><div class="diff-scroll utility-gap"><div class="diff-header"><span>原始文本</span><span>修改后文本</span></div><div v-for="(row, index) in result.rows.filter(row => !onlyChanges || row.type !== 'same')" :key="index" class="diff-row" :class="row.type"><div :class="{marked:row.type === 'removed'}"><span class="line-number">{{ row.leftLine }}</span><code>{{ row.left ?? '' }}</code></div><div :class="{marked:row.type === 'added'}"><span class="line-number">{{ row.rightLine }}</span><code>{{ row.right ?? '' }}</code></div></div></div></section></section></template>
<style scoped>
.diff-scroll { overflow: auto; max-height: 650px; border: 1px solid var(--border); border-radius: 14px; }.diff-header,.diff-row { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); min-width: 560px; }.diff-header { background: var(--surface-soft); font-size: 13px; color: var(--text-muted); }.diff-header span { padding: 10px 16px; }.diff-row>div { display: flex; min-height: 28px; border-right: 1px solid var(--border); }.diff-row code { padding: 2px 12px; white-space: pre-wrap; overflow-wrap: anywhere; font-size: 13px; min-width: 0; }.line-number { min-width: 44px; padding: 2px 8px; color: var(--text-subtle); font: 12px/24px Consolas,monospace; text-align: right; background: var(--well); }.removed .marked { background: color-mix(in srgb,var(--danger) 12%,transparent); }.added .marked { background: color-mix(in srgb,var(--success) 12%,transparent); }
</style>
